L.id = "sw-ach-social"
do      -- every object made by this screen carries _lookScope = L.id (Look.Id(obj) = "<screen>:<node id>")
    local function scoped(fn) return function(...) return Look.InScope(L.id, fn, ...) end end
    L.build = scoped(L.build)
    L.sample = scoped(L.sample)
    for k, t in pairs(L.templates) do L.templates[k] = scoped(t) end
end

